export type Cell = [number, number];

const SURVIVAL_NEIGHBOUR_COUNTS = [2, 3];
const BIRTH_NEIGHBOUR_COUNT = 3;

const keyOf = ([x, y]: Cell): string => `${x},${y}`;

const isSameCell = (cell: Cell, other: Cell): boolean =>
  keyOf(cell) === keyOf(other);

const neighboursOf = ([x, y]: Cell): Cell[] =>
  [-1, 0, 1].flatMap((dx) =>
    [-1, 0, 1]
      .filter((dy) => dx !== 0 || dy !== 0)
      .map((dy): Cell => [x + dx, y + dy]),
  );

const isNeighbour = (cell: Cell, other: Cell): boolean =>
  neighboursOf(cell).some((neighbour) => isSameCell(neighbour, other));

const countLiveNeighbours = (cell: Cell, liveCells: Cell[]): number =>
  liveCells.filter((other) => isNeighbour(cell, other)).length;

const isLive = (cell: Cell, liveCells: Cell[]): boolean =>
  liveCells.some((live) => isSameCell(cell, live));
